mapper.select:
SELECT n.notice_id, n.category, n.title, n.fair_id, f.name AS fair_name, n.is_published, n.is_pinned, n.view_count, n.created_at, n.updated_at FROM notice n LEFT JOIN fairs f ON f.fair_id = n.fair_id WHERE n.is_published = 1
AND n.category = #{category}
ORDER BY n.is_pinned DESC, n.created_at DESC

